import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Segmented","description":"","frontmatter":{},"headers":[],"relativePath":"components/segmented.md","filePath":"components/segmented.md"}'),d={name:"components/segmented.md"};function r(i,e,s,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="segmented" tabindex="-1">Segmented <a class="header-anchor" href="#segmented" aria-label="Permalink to &quot;Segmented&quot;">​</a></h1><p>Segmented is an exclusive switch between two to four options.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to switch between views or modes, where every option is seen at once. Five options or more are a <a href="./select">Select</a>. An option with an icon and no label is square and needs an <code>ariaLabel</code>. When the value is derived from elsewhere, pass <code>value</code> and <code>onchange</code> instead of binding it.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td>required</td><td><code>{ value, label?, icon?, ariaLabel?, disabled? }[]</code></td></tr><tr><td><code>value</code></td><td>required</td><td>The chosen value (bindable)</td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The name of the group</td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the chosen value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Each option is a control of the height its container declares, a button&#39;s by default, with pad-md at the sides; neighbours share one line. The chosen option takes the solid surface while the outer line stays line-strong. The text is trimmed to its ink. The group does not wrap and does not shrink its padding: when it does not fit, it scrolls sideways without a scrollbar. The focus ring is drawn inside an option.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/segmented/" title="Segmented" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/segmented/" target="_blank" rel="noopener">Segmented</a></figcaption></figure>',10)])])}const u=t(d,[["render",r]]);export{m as __pageData,u as default};
